{
  "functions": [
    {
      "tag": "size_display",
      "meaning": "size in bytes with unit",
      "class": "class_2_formatted_numeric",
      "value_type": "numeric",
      "target_role": "ordinary_value",
      "context": null,
      "regex": "\\(estimated size ([0-9]+\\.[0-9]+) (B|KB|MB),",
      "replacement": "(estimated size {placeholder},",
      "program": {
        "op": "python_exec",
        "code": "def forward(groups):\n    size = float(groups[0])\n    unit = groups[1]\n    unit_map = {'B': 1, 'KB': 1024, 'MB': 1024**2}\n    bytes_size = int(size * unit_map[unit])\n    return {'stored': [bytes_size], 'layout': [unit]}\n\ndef inverse(record):\n    bytes_size = record['stored'][0]\n    unit = record['layout'][0]\n    unit_map = {'B': 1, 'KB': 1024, 'MB': 1024**2}\n    for u, factor in unit_map.items():\n        if bytes_size % factor == 0 or u == unit:\n            size = bytes_size / factor\n            return f'(estimated size {size:.1f} {u},'\n    return ''"
      }
    }
  ]
}
